{
  "PROP-6a4369e9-inv-029": {
    "property_id": "PROP-6a4369e9-inv-029",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-029",
      "classification": "potential-vulnerability",
      "code_path": "beacon-chain/sync/rpc_blob_sidecars_by_range.go::streamBlobBatch::L21-58",
      "proof_trace": "The streamBlobBatch function serves all blobs in the requested range without checking if blob epoch < FULU_FORK_EPOCH. MaxBlobsForEpoch() is used only for iteration count, not filtering. No epoch-based guard exists in blobSidecarsByRangeRPCHandler or validateBlobsByRange to enforce the transition boundary.",
      "attack_scenario": "During transition near FULU_FORK_EPOCH, a peer requests blob_sidecars_by_range with a range spanning the fork boundary. The handler serves blobs from both pre-Fulu and post-Fulu epochs without filtering, violating the protocol requirement that only pre-Fulu blobs should be served via this RPC after the fork.",
      "checklist_id": "PROP-6a4369e9-inv-029"
    },
    "text": "During transition, blob_sidecars_by_range must serve only pre-Fulu epoch blobs.",
    "assertion": "forall sidecar in transition_resp: compute_epoch(sidecar.slot) < FULU_FORK_EPOCH",
    "covers": "SG-011",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

